// @generated by:gauntlet run:godseye-local-agent-center
import { randomUUID } from "node:crypto";
import { describe, expect, it } from "vitest";
import {
  AgentLimits,
  AgentOverview,
  AgentProfile,
  AgentTask,
  CreateAgentProfile,
  LaunchAgentTask,
} from "../packages/contracts/src/agents.js";

const limits = {
  maxOutputTokens: 1024,
  timeoutSeconds: 120,
  maxCostMicros: 10000,
  maxTurns: 1,
  maxRequests: 1,
};
const configuration = () => ({
  projectId: randomUUID(),
  environmentId: randomUUID(),
  role: "operations",
  model: "gpt-6-luna",
  expectedProjectRevision: 0,
  expectedEnvironmentRevision: 0,
  limits,
});

describe("strict Agent Center public contracts", () => {
  it("T-AC-731 refuses authority fields and arbitrary runtime endpoints in profile requests", () => {
    for (const field of [
      "endpoint",
      "baseUrl",
      "apiKey",
      "home",
      "tools",
      "provider",
      "providerRunId",
      "skill",
    ]) {
      expect(
        CreateAgentProfile.safeParse({ ...configuration(), [field]: "unreviewed" }).success,
      ).toBe(false);
    }
    expect(CreateAgentProfile.safeParse(configuration()).success).toBe(true);
  });
  it("T-AC-729 enforces finite positive admission and one-turn one-request policy", () => {
    for (const change of [
      { maxOutputTokens: 31 },
      { maxOutputTokens: 2049 },
      { maxCostMicros: 0 },
      { maxCostMicros: 100001 },
      { timeoutSeconds: 4 },
      { timeoutSeconds: 301 },
      { maxCostMicros: Infinity },
      { timeoutSeconds: NaN },
      { maxOutputTokens: 1.5 },
    ])
      expect(AgentLimits.safeParse({ ...limits, ...change }).success).toBe(false);
    expect(AgentLimits.safeParse(limits).success).toBe(true);
    for (const change of [{ maxTurns: 2 }, { maxRequests: 2 }])
      expect(
        CreateAgentProfile.safeParse({ ...configuration(), limits: { ...limits, ...change } })
          .success,
      ).toBe(false);
  });
  it("T-AC-731 refuses malformed role, model and scope identities", () => {
    for (const change of [
      { role: "administrator" },
      { role: "../security" },
      { model: "expensive-arbitrary-model" },
      { projectId: "owner" },
      { environmentId: "../foreign" },
      { expectedProjectRevision: -1 },
      { expectedEnvironmentRevision: 0.5 },
    ])
      expect(CreateAgentProfile.safeParse({ ...configuration(), ...change }).success).toBe(false);
  });
  it("T-AC-731 bounds and validates task input without admitting caller-selected authority", () => {
    const launch = {
      profileId: randomUUID(),
      expectedRevision: 0,
      input: "A short bounded request",
    };
    expect(LaunchAgentTask.safeParse(launch).success).toBe(true);
    for (const change of [
      { input: " " },
      { input: "x".repeat(8193) },
      { profileId: "foreign" },
      { expectedRevision: -1 },
      { providerRunId: "chosen" },
      { tools: ["shell"] },
      { model: "other" },
    ])
      expect(LaunchAgentTask.safeParse({ ...launch, ...change }).success).toBe(false);
  });
  it("T-AC-731 refuses oversized or key-bearing successful metadata payloads", () => {
    expect(
      AgentOverview.safeParse({
        status: "available",
        profiles: [],
        tasks: [],
        roles: [],
        models: [],
        defaults: limits,
        tools: [],
        message: "ok",
        apiKey: "not-real",
      }).success,
    ).toBe(false);
    const instant = new Date().toISOString();
    const profile = {
      id: randomUUID(),
      projectId: randomUUID(),
      environmentId: randomUUID(),
      role: "operations",
      model: "gpt-6-luna",
      limits,
      revision: 0,
      projectRevision: 0,
      environmentRevision: 0,
      hash: "a".repeat(64),
      paused: false,
      skill: { id: "godseye-context", version: "1.0.0", sha256: "b".repeat(64) },
      runtime: "unconfigured",
      tools: [],
      busy: false,
      activeTaskId: null,
      createdAt: instant,
      updatedAt: instant,
    };
    expect(AgentProfile.safeParse(profile).success).toBe(true);
    expect(AgentProfile.safeParse({ ...profile, tools: ["shell"] }).success).toBe(false);
    const task = {
      id: randomUUID(),
      profileId: profile.id,
      projectId: profile.projectId,
      environmentId: profile.environmentId,
      profileRevision: 0,
      runId: null,
      state: "queued",
      providerRunId: null,
      input: "Bounded fixture input",
      output: null,
      reason: null,
      usage: { inputTokens: null, outputTokens: null, costState: "reserved-conservatively" },
      createdAt: instant,
      updatedAt: instant,
      finishedAt: null,
    };
    expect(AgentTask.safeParse(task).success).toBe(true);
    expect(AgentTask.safeParse({ ...task, output: "x".repeat(32769) }).success).toBe(false);
  });
});
